/* ============================================
   SOURCE CHIP COMPONENT
   Numbered citation pill linking a claim to
   its source. Anchor when href is set, plain
   span otherwise.
   ============================================ */

.ds-source-chip {
  /* Layout */
  display: inline-flex;
  align-items: center;
  gap: var(--gap-100); /* 4px */

  /* Spacing */
  padding: var(--padding-050) var(--padding-200); /* 2px 8px */

  /* Shape — borderless pill on the secondary container */
  border-radius: var(--radius-pill);
  background-color: var(--color-bg-container-secondary);

  /* Typography */
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-secondary);

  /* The pill shape is the affordance — never an underline */
  text-decoration: none;
  cursor: default;

  transition: background-color var(--motion-duration-fast) var(--motion-ease-standard),
    color var(--motion-duration-fast) var(--motion-ease-standard);
}

/* ============================================
   INDEX — citation numeral in its own circle
   ============================================ */

.ds-source-chip__index {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  min-width: var(--icon-size-500);
  height: var(--icon-size-500);
  border-radius: var(--radius-pill);
  background-color: var(--color-bg-container-tertiary);

  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
  line-height: 1;
  font-variant-numeric: tabular-nums;
  color: var(--color-text-tertiary);
}

/* ============================================
   ICON (leading, when no index)
   ============================================ */

.ds-source-chip__icon {
  flex-shrink: 0;
  --icon-size: var(--icon-size-500);
  line-height: 1;
  color: var(--color-icon-primary);
}

/* ============================================
   TITLE — truncates with an ellipsis
   ============================================ */

.ds-source-chip__title {
  max-width: 24ch;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

/* ============================================
   LINK (rendered as <a>)
   ============================================ */

.ds-source-chip--link {
  cursor: pointer;
}

.ds-source-chip--link:hover {
  background-color: var(--color-bg-container-tertiary);
  color: var(--color-text-primary);
}

/* ============================================
   FOCUS
   ============================================ */

.ds-source-chip--link:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

/* Icons take the colour of the text around them. Explicit, not just
   inherited by default: a consumer stylesheet that sets a colour on
   .material-symbols-rounded itself (a common global default) would
   otherwise override inheritance and detach the icon from the state
   colours this component sets on its parents. */
.ds-source-chip .material-symbols-rounded {
  color: inherit;
}

import React from 'react';
import './SourceChip.css';
import '../../fonts/material-symbols.css';

/** Props owned by SourceChip itself — everything else falls through to the root element. */
type SourceChipOwnProps = {
  /** The source name, e.g. "Design tokens quarterly". Truncates with an ellipsis when long. */
  title: string;
  /** Citation number, rendered as a leading numeral in its own small badge circle. */
  index?: number;
  /**
   * Leading icon — a Material Symbol name (string) or custom element (ReactNode).
   * The icon and the index share the leading slot: when both are passed, `index` wins
   * and the icon is not rendered.
   */
  icon?: string | React.ReactNode;
  /** Optional href — renders as an `<a>` instead of a `<span>`. */
  href?: string;
  /** Additional CSS classes */
  className?: string;
};

export interface SourceChipProps
  extends SourceChipOwnProps,
    Omit<React.ComponentPropsWithoutRef<'a'>, keyof SourceChipOwnProps> {}

/**
 * SourceChip is the numbered citation pill linking a claim to its source.
 * It renders inline after a sentence or in a sources row under an assistant
 * chat message: a leading citation number (or icon) beside a truncating
 * source title.
 *
 * Renders an `<a>` when `href` is supplied, a plain `<span>` otherwise.
 * Forwards a ref to whichever element it renders, and spreads unrecognised
 * props onto it — `target` and `rel` pass through as native anchor attributes.
 */
export const SourceChip = React.forwardRef<HTMLAnchorElement | HTMLSpanElement, SourceChipProps>(
  ({ title, index, icon, href, className = '', ...rest }, ref) => {
    const baseClass = 'ds-source-chip';

    const classes = [baseClass, href ? `${baseClass}--link` : '', className]
      .filter(Boolean)
      .join(' ');

    // The leading slot: the citation number wins over the icon when both are set.
    const leading =
      index !== undefined ? (
        <span className={`${baseClass}__index`}>{index}</span>
      ) : icon ? (
        <span className={`${baseClass}__icon`} aria-hidden="true">
          {typeof icon === 'string' ? (
            <span className="material-symbols-rounded">{icon}</span>
          ) : (
            icon
          )}
        </span>
      ) : null;

    const content = (
      <>
        {leading}
        <span className={`${baseClass}__title`}>{title}</span>
      </>
    );

    if (href) {
      return (
        <a {...rest} ref={ref as React.Ref<HTMLAnchorElement>} className={classes} href={href}>
          {content}
        </a>
      );
    }

    return (
      <span
        {...(rest as React.ComponentPropsWithoutRef<'span'>)}
        ref={ref as React.Ref<HTMLSpanElement>}
        className={classes}
      >
        {content}
      </span>
    );
  },
);

SourceChip.displayName = 'SourceChip';
